<script lang="ts">
 import {Search,X} from '@lucide/svelte';
 import type {BalanceFilter} from './balance-view';
 import {translator} from './i18n';
 export let language:'ru'|'ro';export let label:string;export let items:{id:string;code:string;name:string;address?:string}[];export let filter:BalanceFilter;
 let open=false,query='';$:t=translator(language);
 $:matches=items.filter(r=>(r.code+' '+r.name+' '+(r.address||'')).toLocaleLowerCase().includes(query.toLocaleLowerCase()));
 $:multiple=filter.operator==='in'||filter.operator==='not-in';
 function choose(id:string){if(multiple){filter={...filter,enabled:true,values:filter.values.includes(id)?filter.values.filter(v=>v!==id):[...filter.values,id]};}else{filter={...filter,enabled:true,values:[id]};open=false;}}
</script>
<div class="filter-line"><label><input type="checkbox" bind:checked={filter.enabled}/>{label}</label><select aria-label={t('Тип сравнения','Tip comparație')} bind:value={filter.operator} onchange={()=>{if(!multiple)filter={...filter,values:filter.values.slice(0,1)};}}><option value="eq">{t('Равно','Egal')}</option><option value="ne">{t('Не равно','Diferit')}</option><option value="in">{t('В списке','În listă')}</option><option value="not-in">{t('Не в списке','Nu în listă')}</option></select><input aria-label={label} readonly value={filter.values.map(id=>items.find(r=>r.id===id)?.name||id).join('; ')}/><button class="lookup" aria-label={t('Выбрать из справочника','Selectează din catalog')} onclick={()=>open=true}>…</button><button class="lookup" aria-label={t('Очистить','Șterge')} onclick={()=>filter={...filter,values:[]}}><X size={14}/></button></div>
{#if open}<div class="lookup-backdrop" role="presentation"><div class="lookup-window" role="dialog" aria-modal="true" aria-label={label} tabindex="-1" onkeydown={e=>{if(e.key==='Escape')open=false;}}><header><strong>{label} · {t('Выбор элемента','Selectare element')}</strong><button class="icon-button" aria-label={t('Закрыть','Închide')} onclick={()=>open=false}><X size={18}/></button></header><label class="lookup-search"><Search size={16}/><input aria-label={t('Поиск','Căutare')} bind:value={query}/></label><div class="lookup-table"><table><thead><tr>{#if multiple}<th></th>{/if}<th>{t('Код / номер','Cod / număr')}</th><th>{t('Наименование','Denumire')}</th><th>{t('Адрес','Adresă')}</th></tr></thead><tbody>{#each matches as item}<tr>{#if multiple}<td><input type="checkbox" aria-label={item.name} checked={filter.values.includes(item.id)} onchange={()=>choose(item.id)}/></td>{/if}<td>{item.code}</td><td><button onclick={()=>choose(item.id)}>{item.name}</button></td><td>{item.address||''}</td></tr>{/each}</tbody></table></div></div></div>{/if}
<style>.filter-line{display:grid;grid-template-columns:155px 125px minmax(0,1fr) 32px 32px;gap:0;align-items:center;margin:6px 0}.filter-line label{display:flex;align-items:center;gap:7px}.filter-line input{min-width:0;width:100%}.filter-line label input{width:auto}.lookup{height:34px;padding:0;display:grid;place-items:center;background:transparent;color:var(--text);border:1px solid var(--border)}.lookup-backdrop{position:fixed;inset:0;z-index:27000;display:grid;place-items:center;background:#0004}.lookup-window{width:min(850px,92vw);max-height:80vh;background:var(--surface,#272727);color:var(--text);border:1px solid var(--border);box-shadow:0 12px 45px #0006;padding:16px;display:flex;flex-direction:column;gap:12px}.lookup-window header{display:flex;justify-content:space-between;align-items:center}.lookup-search{display:flex;gap:10px;align-items:center}.lookup-search input{width:100%}.lookup-table{overflow:auto;min-height:200px}.lookup-table button{border:0;background:transparent;color:inherit;text-align:left;width:100%;padding:8px}.lookup-table button:hover{background:#80808020}@media(max-width:650px){.filter-line{grid-template-columns:100px 100px minmax(0,1fr) 30px 30px}}</style>

